"""P4 JSON cases shared with Ajv; generated by the synthetic demo script."""
from pathlib import Path
import unittest
from static_comic.contracts import read_json, validate


class TransitionContractTests(unittest.TestCase):
    def test_shared_transition_contract_cases(self):
        cases = read_json((Path(__file__).resolve().parents[1] / "fixtures/transition-contract-cases.json").read_bytes())
        for case in cases:
            with self.subTest(case=case["name"]):
                if case["valid"]:
                    validate(case["kind"], case["value"])
                else:
                    with self.assertRaises(ValueError):
                        validate(case["kind"], case["value"])
